cat > /tmp/send_touch.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <IOKit/IOKitLib.h>

int main(int argc, char *argv[]) {
    if (argc != 4) {
        printf("Usage: %s <device_udid> <x> <y>\n", argv[0]);
        return 1;
    }

    const char *udid = argv[1];
    int x = atoi(argv[2]);
    int y = atoi(argv[3]);

    // Try to connect to the Simulator Services via IOKit
    CFMutableDictionaryRef matchingDict = IOServiceMatching("AppleSimulatorHIDDevice");
    if (!matchingDict) {
        fprintf(stderr, "Failed to create matching dictionary\n");
        return 1;
    }

    io_iterator_t iterator;
    kern_return_t result = IOServiceGetMatchingServices(kIOMasterPortDefault, matchingDict, &iterator);
    if (result != KERN_SUCCESS) {
        fprintf(stderr, "IOServiceGetMatchingServices failed\n");
        return 1;
    }

    printf("Found HID services. Attempting to send touch at (%d, %d)\n", x, y);
    return 0;
}
EOF

gcc -o /tmp/send_touch /tmp/send_touch.c -framework IOKit 2>&1 || echo "Compilation might have some warnings but let's try"

