import XCTest

class BlueskyTest: XCTestCase {
    func testTapFeedsTab() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()

        // Wait for the app to be ready
        sleep(2)

        // Try to find and tap the Feeds tab
        // The Feeds tab should be in the tab bar
        let feedsButton = app.buttons["Feeds"]
        if feedsButton.exists {
            feedsButton.tap()
            print("Successfully tapped Feeds tab")
        } else {
            // Try finding by accessibility label or other methods
            let tabBar = app.tabBars.firstMatch
            if tabBar.exists {
                // Count the buttons in the tab bar
                let buttons = tabBar.buttons
                if buttons.count >= 2 {
                    buttons.element(boundBy: 1).tap()
                    print("Tapped second tab")
                }
            }
        }

        // Give it time to navigate
        sleep(1)
    }
}
EOF

